263→// If the slice is empty, removes the key from rawHooks.
264→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) {
265→	if len(entries) == 0 {
266→		delete(rawHooks, hookType)
267→		return
268→	}
269→	data, err := json.Marshal(entries)
270→	if err != nil {
271→		return // Silently ignore marshal errors (shouldn't happen)
272→	}
273→	rawHooks[hookType] = data
