276→// hookBashExists checks if a hook with the given bash command already exists.
277→func hookBashExists(entries []CopilotHookEntry, bash string) bool {
278→	for _, entry := range entries {
279→		if entry.Bash == bash {
280→			return true
281→		}
282→	}
283→	return false
284→}
