286→// isEntireHook checks if a hook entry's bash command belongs to Entire.
287→func isEntireHook(bash string) bool {
288→	for _, prefix := range entireHookPrefixes {
289→		if strings.HasPrefix(bash, prefix) {
290→			return true
291→		}
292→	}
293→	return false
294→}
295→
296→// hasEntireHook checks if any entry in the slice is an Entire hook.
297→func hasEntireHook(entries []CopilotHookEntry) bool {
298→	for _, entry := range entries {
299→		if isEntireHook(entry.Bash) {
300→			return true
301→		}
302→	}
303→	return false
304→}
305→
306→// removeEntireHooks removes all Entire hooks from the slice.
307→func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
308→	result := make([]CopilotHookEntry, 0, len(entries))
309→	for _, entry := range entries {
310→		if !isEntireHook(entry.Bash) {
311→			result = append(result, entry)
312→		}
313→	}
