    rawFile = map[string]json.RawMessage{"version": json.RawMessage(`1`)}
} else {
    return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
}

// UninstallHooks - similarly:
data, err := os.ReadFile(hooksPath)
if err != nil {
    if os.IsNotExist(err) {
        return nil // No hooks file means nothing to uninstall
    }
    return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
}
```

Keep the `//nolint:gosec` on the ReadFile calls (path is constructed from repo root + fixed path).

**Issue 5: AreHooksInstalled should log errors**

`AreHooksInstalled` (line ~215) currently returns `false` on read or parse errors. Add context-based logging for the error cases. The function signature takes `ctx context.Context`, so use `logging.Warn(ctx, ...)`:

```go
import "github.com/entireio/cli/cmd/entire/cli/logging"

func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
    // ...
    data, err := os.ReadFile(hooksPath)
    if err != nil {
        if !os.IsNotExist(err) {
            logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
        }
        return false
    }
    var hooksFile CopilotHooksFile
    if err := json.Unmarshal(data, &hooksFile); err != nil {
        logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
        return false
    }
    // ...
}
```

**Test Gap 10: Test malformed JSON in existing hooks file**

Add tests for `InstallHooks` and `UninstallHooks` when `entire.json` contains invalid JSON:
- `TestInstallHooks_MalformedExistingFile` — writes garbage to the file, calls InstallHooks, expects an error
- `TestUninstallHooks_MalformedExistingFile` — same for uninstall

**Test Gap 11: Uninstall preserves user hooks in managed types**

