114→	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
115→	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
116→	// new directories. "Yes" is pre-selected, so Enter dismisses it.
117→	foundPrompt := false
