130→	}
131→	if !foundPrompt {
132→		_ = s.Close()
133→		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
134→	}
135→	s.stableAtSend = ""
136→
137→	return s, nil
138→}
