 40→// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
 41→// If force is true, removes existing Entire hooks before installing.
 42→// Returns the number of hooks installed.
 43→// Unknown top-level fields and hook types are preserved on round-trip.
 44→func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 45→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 46→	if err != nil {
 47→		worktreeRoot = "."
 48→	}
 49→
 50→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
 51→
 52→	// Use raw maps to preserve unknown fields on round-trip
 53→	var rawFile map[string]json.RawMessage
 54→	var rawHooks map[string]json.RawMessage
 55→
 56→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 57→	if readErr == nil {
 58→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 59→			return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
 60→		}
 61→		if hooksRaw, ok := rawFile["hooks"]; ok {
 62→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 63→				return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
 64→			}
 65→		}
 66→		if _, ok := rawFile["version"]; !ok {
 67→			rawFile["version"] = json.RawMessage(`1`)
 68→		}
 69→	} else {
 70→		rawFile = map[string]json.RawMessage{
 71→			"version": json.RawMessage(`1`),
 72→		}
 73→	}
 74→
 75→	if rawHooks == nil {
 76→		rawHooks = make(map[string]json.RawMessage)
 77→	}
 78→
 79→	// Parse existing entries for each hook type we manage
 80→	hookEntries := make(map[string][]CopilotHookEntry)
 81→	for _, hookName := range c.HookNames() {
 82→		key := hookConfigKey[hookName]
 83→		var entries []CopilotHookEntry
 84→		parseCopilotHookType(rawHooks, key, &entries)
 85→		hookEntries[hookName] = entries
 86→	}
 87→
 88→	// If force, remove existing Entire hooks first
 89→	if force {
 90→		for hookName, entries := range hookEntries {
 91→			hookEntries[hookName] = removeEntireHooks(entries)
 92→		}
 93→	}
 94→
 95→	// Define command prefix
 96→	var cmdPrefix string
 97→	if localDev {
 98→		cmdPrefix = "go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go hooks copilot-cli "
 99→	} else {
100→		cmdPrefix = "entire hooks copilot-cli "
101→	}
102→
103→	count := 0
104→
105→	// Add hooks that don't already exist
106→	for _, hookName := range c.HookNames() {
107→		cmd := cmdPrefix + hookName
108→		entries := hookEntries[hookName]
109→		if !hookBashExists(entries, cmd) {
110→			entries = append(entries, CopilotHookEntry{
111→				Type:    "command",
112→				Bash:    cmd,
113→				Comment: "Entire CLI",
114→			})
115→			hookEntries[hookName] = entries
116→			count++
117→		}
118→	}
119→
120→	if count == 0 {
121→		return 0, nil
122→	}
123→
124→	// Marshal modified hook types back into rawHooks
125→	for _, hookName := range c.HookNames() {
126→		key := hookConfigKey[hookName]
127→		marshalCopilotHookType(rawHooks, key, hookEntries[hookName])
128→	}
129→
130→	// Marshal hooks and update raw file
131→	hooksJSON, err := json.Marshal(rawHooks)
132→	if err != nil {
133→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
134→	}
135→	rawFile["hooks"] = hooksJSON
136→
137→	// Write to file
138→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
139→		return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
140→	}
141→
142→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
143→	if err != nil {
144→		return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
145→	}
146→
147→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
148→		return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
149→	}
150→
151→	return count, nil
152→}
