154→// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
155→// Unknown top-level fields and hook types are preserved on round-trip.
156→func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
157→	worktreeRoot, err := paths.WorktreeRoot(ctx)
158→	if err != nil {
159→		worktreeRoot = "."
160→	}
161→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
162→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
163→	if err != nil {
164→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
165→	}
166→
167→	var rawFile map[string]json.RawMessage
168→	if err := json.Unmarshal(data, &rawFile); err != nil {
169→		return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
170→	}
171→
172→	var rawHooks map[string]json.RawMessage
173→	if hooksRaw, ok := rawFile["hooks"]; ok {
174→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
175→			return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
176→		}
177→	}
178→	if rawHooks == nil {
179→		rawHooks = make(map[string]json.RawMessage)
180→	}
181→
182→	// Parse and remove Entire hooks from each hook type we manage
183→	for _, hookName := range c.HookNames() {
184→		key := hookConfigKey[hookName]
185→		var entries []CopilotHookEntry
186→		parseCopilotHookType(rawHooks, key, &entries)
187→		entries = removeEntireHooks(entries)
188→		marshalCopilotHookType(rawHooks, key, entries)
189→	}
190→
191→	// Marshal hooks back (preserving unknown hook types)
192→	if len(rawHooks) > 0 {
193→		hooksJSON, err := json.Marshal(rawHooks)
194→		if err != nil {
195→			return fmt.Errorf("failed to marshal hooks: %w", err)
196→		}
197→		rawFile["hooks"] = hooksJSON
198→	} else {
199→		delete(rawFile, "hooks")
200→	}
201→
202→	// Write back
203→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
204→	if err != nil {
205→		return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
206→	}
207→
208→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
209→		return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
210→	}
211→	return nil
212→}
