214→// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
215→func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
216→	worktreeRoot, err := paths.WorktreeRoot(ctx)
217→	if err != nil {
218→		worktreeRoot = "."
219→	}
220→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
221→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
222→	if err != nil {
223→		return false
224→	}
225→
226→	var hooksFile CopilotHooksFile
227→	if err := json.Unmarshal(data, &hooksFile); err != nil {
228→		return false
229→	}
230→
231→	return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
232→		hasEntireHook(hooksFile.Hooks.SessionStart) ||
233→		hasEntireHook(hooksFile.Hooks.AgentStop) ||
234→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
235→		hasEntireHook(hooksFile.Hooks.SubagentStop) ||
236→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
237→		hasEntireHook(hooksFile.Hooks.PostToolUse) ||
238→		hasEntireHook(hooksFile.Hooks.ErrorOccurred)
239→}
