253→// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
254→// Silently ignores parse errors (leaves target unchanged).
255→func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) {
256→	if data, ok := rawHooks[hookType]; ok {
257→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
258→		json.Unmarshal(data, target)
259→	}
260→}
261→
262→// marshalCopilotHookType marshals a hook type back into rawHooks.
263→// If the slice is empty, removes the key from rawHooks.
264→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) {
265→	if len(entries) == 0 {
266→		delete(rawHooks, hookType)
267→		return
268→	}
269→	data, err := json.Marshal(entries)
270→	if err != nil {
271→		return // Silently ignore marshal errors (shouldn't happen)
272→	}
273→	rawHooks[hookType] = data
274→}
