 17→// copilotEvent is a single line in events.jsonl.
 18→type copilotEvent struct {
 19→	Type      string          `json:"type"`
 20→	Data      json.RawMessage `json:"data"`
 21→	ID        string          `json:"id"`
 22→	Timestamp string          `json:"timestamp"`
 23→	ParentID  string          `json:"parentId"`
 24→}
 25→
 26→const (
 27→	eventTypeUserMessage  = "user.message"
 28→	eventTypeAssistantMsg = "assistant.message"
 29→	eventTypeToolExecDone = "tool.execution_complete"
 30→)
 31→
 32→// userMessageData is the data payload for user.message events.
 33→// IMPORTANT: The field is "content", not "message" — verified from real Copilot JSONL.
 34→type userMessageData struct {
 35→	Content string `json:"content"`
 36→}
 37→
 38→type assistantMessageData struct {
 39→	Content string `json:"content"`
 40→}
 41→
 42→type toolExecCompleteData struct {
 43→	ToolCallID    string        `json:"toolCallId"`
 44→	ToolTelemetry toolTelemetry `json:"toolTelemetry"`
 45→}
 46→
 47→type toolTelemetry struct {
 48→	Metrics    toolMetrics    `json:"metrics"`
 49→	Properties toolProperties `json:"properties"`
 50→}
 51→
 52→type toolMetrics struct {
 53→	LinesAdded   int `json:"linesAdded"`
 54→	LinesRemoved int `json:"linesRemoved"`
 55→}
 56→
 57→// toolProperties contains string-encoded metadata from tool execution.
 58→// filePaths is a JSON-encoded string array, e.g. "[\"path/to/file.txt\"]".
 59→type toolProperties struct {
 60→	FilePaths string `json:"filePaths"`
 61→}
 62→
 63→// parseEventsFromBytes scans JSONL data and returns all parsed events.
 64→// Malformed lines are silently skipped.
 65→func parseEventsFromBytes(data []byte) []copilotEvent {
 66→	return parseEventsFromOffset(data, 0)
 67→}
 68→
 69→// parseEventsFromOffset scans JSONL data and returns events starting after
 70→// the first startOffset lines. Malformed lines are silently skipped.
 71→func parseEventsFromOffset(data []byte, startOffset int) []copilotEvent {
 72→	var events []copilotEvent
 73→	scanner := bufio.NewScanner(bytes.NewReader(data))
 74→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 10*1024*1024) // 10 MB max line
 75→	lineNum := 0
 76→
 77→	for scanner.Scan() {
 78→		lineNum++
 79→		if lineNum <= startOffset {
 80→			continue
 81→		}
 82→
 83→		line := scanner.Bytes()
 84→		if len(line) == 0 {
 85→			continue
 86→		}
 87→
 88→		var ev copilotEvent
 89→		if err := json.Unmarshal(line, &ev); err != nil {
 90→			continue // skip malformed lines
 91→		}
 92→		events = append(events, ev)
 93→	}
 94→
 95→	return events
 96→}
 97→
 98→// extractModifiedFilesFromEvents collects file paths from tool.execution_complete
 99→// events and returns a deduplicated list.
100→func extractModifiedFilesFromEvents(events []copilotEvent) []string {
101→	seen := make(map[string]bool)
102→	var files []string
103→
104→	for i := range events {
105→		if events[i].Type != eventTypeToolExecDone {
106→			continue
107→		}
108→
109→		var data toolExecCompleteData
110→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
111→			continue
112→		}
113→
114→		// filePaths is a JSON-encoded string array in properties, e.g. "[\"path/to/file\"]"
115→		if data.ToolTelemetry.Properties.FilePaths == "" {
116→			continue
117→		}
118→		var paths []string
119→		if err := json.Unmarshal([]byte(data.ToolTelemetry.Properties.FilePaths), &paths); err != nil {
120→			continue
121→		}
122→		for _, fp := range paths {
123→			if fp != "" && !seen[fp] {
124→				seen[fp] = true
125→				files = append(files, fp)
126→			}
127→		}
128→	}
129→
130→	return files
131→}
132→
133→// extractPromptsFromEvents collects content from user.message events.
134→func extractPromptsFromEvents(events []copilotEvent) []string {
135→	var prompts []string
136→
137→	for i := range events {
138→		if events[i].Type != eventTypeUserMessage {
139→			continue
140→		}
141→
142→		var data userMessageData
143→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
144→			continue
145→		}
146→
147→		if data.Content != "" {
148→			prompts = append(prompts, data.Content)
149→		}
150→	}
151→
152→	return prompts
153→}
154→
155→// extractSummaryFromEvents returns the content of the last assistant.message event.
156→func extractSummaryFromEvents(events []copilotEvent) string {
157→	for i := len(events) - 1; i >= 0; i-- {
158→		if events[i].Type != eventTypeAssistantMsg {
159→			continue
160→		}
161→
162→		var data assistantMessageData
163→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
164→			continue
165→		}
166→
167→		if data.Content != "" {
168→			return data.Content
169→		}
170→	}
171→
172→	return ""
173→}
