175→// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
176→// Copilot CLI uses JSONL format, so position is the number of lines.
177→// This is a lightweight operation that only counts lines without parsing JSON.
178→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
179→// Returns 0 if the file doesn't exist or is empty.
180→func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
181→	if path == "" {
182→		return 0, nil
183→	}
184→
185→	file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
186→	if err != nil {
187→		if os.IsNotExist(err) {
188→			return 0, nil
189→		}
190→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
191→	}
192→	defer file.Close()
193→
194→	reader := bufio.NewReader(file)
195→	lineCount := 0
196→
197→	for {
198→		line, readErr := reader.ReadBytes('\n')
199→		if readErr != nil {
200→			if readErr == io.EOF {
201→				if len(line) > 0 {
202→					lineCount++ // Count final line without trailing newline
203→				}
204→				break
205→			}
206→			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
207→		}
208→		lineCount++
209→	}
210→
211→	return lineCount, nil
212→}
213→
214→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
215→// For Copilot CLI (JSONL format), offset is the starting line number.
216→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
217→// Returns:
218→//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
219→//   - currentPosition: total number of lines in the file
220→//   - error: any error encountered during reading
221→func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
222→	if path == "" {
223→		return nil, 0, nil
224→	}
225→
226→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
227→	if openErr != nil {
228→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
229→	}
230→	defer file.Close()
231→
232→	reader := bufio.NewReader(file)
233→	var events []copilotEvent
234→	lineNum := 0
235→
236→	for {
237→		lineData, readErr := reader.ReadBytes('\n')
238→		if readErr != nil && readErr != io.EOF {
239→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
240→		}
241→
242→		if len(lineData) > 0 {
243→			lineNum++
244→			if lineNum > startOffset {
245→				var ev copilotEvent
246→				if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
247→					events = append(events, ev)
248→				}
249→				// Skip malformed lines silently
250→			}
251→		}
252→
253→		if readErr == io.EOF {
254→			break
255→		}
256→	}
257→
258→	return extractModifiedFilesFromEvents(events), lineNum, nil
259→}
