261→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
262→func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
263→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
264→	if err != nil {
265→		return nil, fmt.Errorf("failed to read transcript: %w", err)
266→	}
267→
268→	events := parseEventsFromOffset(data, fromOffset)
269→	return extractPromptsFromEvents(events), nil
270→}
271→
272→// ExtractSummary extracts the last assistant message as a session summary.
273→func (c *CopilotCLIAgent) ExtractSummary(sessionRef string) (string, error) {
274→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
275→	if err != nil {
276→		return "", fmt.Errorf("failed to read transcript: %w", err)
277→	}
278→
279→	events := parseEventsFromBytes(data)
280→	return extractSummaryFromEvents(events), nil
281→}
